// LegacyDetail mimics a message generated by an APIv1-only protoc-gen-go.
type LegacyDetail struct {
	Reason string `protobuf:"bytes,1,opt,name=reason,proto3" json:"reason,omitempty"`
}

func (m *LegacyDetail) Reset()         { *m = LegacyDetail{} }
func (m *LegacyDetail) String() string { return protov1.CompactTextString(m) }
func (*LegacyDetail) ProtoMessage()    {}

func init() { protov1.RegisterType((*LegacyDetail)(nil), "legacytest.LegacyDetail") }

func TestLegacyDetailRoundTrip(t *testing.T) {
	s, err := status.New(codes.Internal, "x").WithDetails(&LegacyDetail{Reason: "r"})
	if err != nil {
		t.Fatal(err)
	}
	d := s.Details()[0]
	_, ok := d.(*LegacyDetail)
	fmt.Printf("RESULT type=%T assertsToLegacyDetail=%v\n", d, ok)
}
EOF
